//! The public views: the response bodies match the Python API's (fixtures generated by the
//! Python runtime, see `fixtures/*.py`), the `public_event` masking of
//! `tests/test_cloud_runtime_events.py`, and the turn prompt byte for byte.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod app_support;

use std::collections::BTreeMap;

use app_support::*;
use limina_core::{Timestamp, now};
