use serde::Serialize;
use serde_json::{Map, Value, json};

/// The JSON's structure: object keys in order, value kinds, array lengths.
fn skeleton(value: &Value) -> Value {
    match value {
        Value::Null => json!("null"),
        Value::Bool(_) => json!("bool"),
        Value::Number(number) if number.is_f64() => json!("float"),
        Value::Number(_) => json!("int"),
        Value::String(_) => json!("string"),
        Value::Array(items) => Value::Array(items.iter().map(skeleton).collect()),
        Value::Object(map) => Value::Object(
            map.iter().map(|(key, item)| (key.clone(), skeleton(item))).collect::<Map<_, _>>(),
        ),
    }
}

fn to_json<T: Serialize>(value: &T) -> Value {
    serde_json::to_value(value).unwrap()
}

/// Replays the recorded session (`fixtures/app_shapes.json`) through the operations and compares every response with
/// the Python runtime's: same keys in the same order, same nullability and value kinds, and the
/// same values where they are deterministic.
#[tokio::test]
async fn responses_match_the_python_api() {
    let python: Map<String, Value> =
        serde_json::from_str(include_str!("fixtures/app_shapes.json")).unwrap();
    let mut done = complete();
    done.decision.summary = "Done.".into();
    done.decision.current_objective = "O".into();
    done.decision.next_step = "N".into();
    done.continuation_id = Some("c".into());
    done.turn_id = "t".into();
    done.usage = Some(limina_domain::usage::RuntimeUsage {
        input_tokens: Some(1),
        output_tokens: Some(2),
        ..Default::default()
    });
    let agent =
        ScriptedSession::always(Reply::ok(done).continuation("c").event(RuntimeEvent::new(
            "runtime.codex",
            "hello",
            detail(json!({"kind": "message", "text": "hi"})),
        )));
    let test = runtime(agent).await;
    let ops = test.ops();
    let me = owner();
    let mut rust = Map::new();
    let mut record = |name: &str, value: Value| {
        rust.insert(name.to_owned(), value);
    };

    let project = NewProject {
        slug: "p".into(),
        name: "P".into(),
        mission: "M".into(),
        success_criteria: "S".into(),
        context: String::new(),
        runtime: None,
        model: None,
        reasoning_effort: None,
    };
    record("create", to_json(&ops.create_project(project, &key(), &me).await.unwrap()));
    record("list", to_json(&ops.list_projects(false, None, 100, &me).await.unwrap()));
    record("get", to_json(&ops.get_project("p", &me).await.unwrap()));
    record("status", to_json(&ops.get_status("p", &me).await.unwrap()));
    let changes = limina_domain::collaboration::DraftChanges {
        context: Some("ctx".into()),
        ..Default::default()
    };
    record("patch", to_json(&ops.update_project("p", &changes, &me).await.unwrap()));
    record("templates", to_json(&ops.kickoff_templates()));
    record("preflight", to_json(&ops.preflight("p", &me).await.unwrap()));
    record("engines", to_json(&ops.engine_availability().await));
    record("engine_accounts", to_json(&ops.engine_accounts("p", &me).await.unwrap()));
    record("var", to_json(&ops.set_variable("p", "V", "x", &key(), &me).await.unwrap()));
    record("secret", to_json(&ops.set_secret("p", "S", "y", &key(), &me).await.unwrap()));
    record("resources", to_json(&ops.list_resources("p", &me).await.unwrap()));
    record("members", to_json(&ops.members("p", &me).await.unwrap()));
    let member = MemberChange {
        subject: "v".into(),
        display_name: "V".into(),
        email: None,
        role: "VIEWER".into(),
    };
    record("set_member", to_json(&ops.set_member("p", &member, &me).await.unwrap()));
    record("ticket", to_json(&ops.issue_live_ticket("p", &me).await.unwrap()));
    let source = SourceInput {
        name: "b".into(),
        source_type: "URL".into(),
        uri: "https://example.test/x".into(),
        media_type: None,
        metadata: Map::new(),
    };
    record("source", to_json(&ops.set_source("p", &source, &me).await.unwrap()));
    record("sources", to_json(&ops.sources("p", &me).await.unwrap()));
    let service = test.runtime.service();
    let hypothesis = NewHypothesis {
        title: "H".into(),
        statement: "s".into(),
        mechanism: "m".into(),
        generalization: "g".into(),
        shortcut_risks: "r".into(),
        test_plan: "t".into(),
    };
    let h = service.create_hypothesis("p", hypothesis, "Limina", &key()).await.unwrap();
    let experiment = NewExperiment {
        hypothesis_id: h.id.clone(),
        title: "E".into(),
        objective: "o".into(),
        procedure: "p".into(),
        success_criteria: "s".into(),
        guardrails: "g".into(),
    };
    let e = service.create_experiment("p", experiment, "Limina", &key()).await.unwrap();
    service.claim_experiment("p", &e.id, 600, "limina:x", &key()).await.unwrap();
    service.append_observation("p", &e.id, "obs", None, "limina:x", &key()).await.unwrap();
    let all = KnowledgeQuery::default();
    record("knowledge", to_json(&ops.query_knowledge("p", &all, &me).await.unwrap()));
    record("knowledge_h", to_json(&ops.get_knowledge("p", &h.id, &me).await.unwrap()));
    record("knowledge_e", to_json(&ops.get_knowledge("p", &e.id, &me).await.unwrap()));
    record("graph", to_json(&ops.knowledge_graph("p", &me).await.unwrap()));
    record("tag", to_json(&ops.add_tag("p", &h.id, "x", &me).await.unwrap()));
    record("comment", to_json(&ops.add_comment("p", &h.id, "b", &key(), &me).await.unwrap()));
    record("revisions", to_json(&ops.revisions("p", &h.id, &me).await.unwrap()));
    let query = detail(json!({"kind": "H"}));
    record("view", to_json(&ops.save_view("p", "n", &query, &me).await.unwrap()));
    record("status2", to_json(&ops.get_status("p", &me).await.unwrap()));
    record("review", to_json(&ops.review("p", None, 50, &me).await.unwrap()));
    record("steer", to_json(&ops.steer("p", "go", "STEER", &key(), &me).await.unwrap()));
    record("guidance", to_json(&ops.guidance("p", None, None, 50, &me).await.unwrap()));
    record("start", to_json(&ops.apply_lifecycle("p", "start", &key(), &me).await.unwrap()));
    test.runtime.supervisor().join("p").await;
    let runs = ops.runs("p", None, None, 50, &me).await.unwrap();
    record("run", to_json(&ops.run("p", &runs.items[0].id, &me).await.unwrap()));
    record("runs", to_json(&runs));
    record("analytics", to_json(&ops.analytics("p", 30, &me).await.unwrap()));
    record("events", to_json(&ops.activity("p", 0, None, 200, &me).await.unwrap()));
    record("snapshot", to_json(&ops.snapshot("p", &me).await.unwrap()));
    record("remove", to_json(&ops.remove_resource("p", "V", &key(), &me).await.unwrap()));
    record("err", ops.get_project("zz", &me).await.unwrap_err().to_body());

    for (name, expected) in &python {
        let expected = &expected["body"];
        let actual = rust.get(name).unwrap_or_else(|| panic!("{name} was not replayed"));
        assert_eq!(skeleton(actual), skeleton(expected), "{name}: {actual:#}");
    }
    // Deterministic bodies are identical.
    for name in ["templates", "preflight", "engines", "engine_accounts", "tag", "err"] {
        assert_eq!(rust[name], python[name]["body"], "{name}");
    }
    let detail_of = |name: &str, index: usize| -> Value {
        let mut event = rust[name]["events"][index].clone();
        event["detail"].as_object_mut().unwrap().remove("run_id");
        event["detail"].clone()
    };
    let python_detail = |name: &str, index: usize| -> Value {
        let mut event = python[name]["body"]["events"][index].clone();
        event["detail"].as_object_mut().unwrap().remove("run_id");
        event["detail"].clone()
    };
    for index in 0..3 {
        assert_eq!(detail_of("run", index), python_detail("run", index));
    }
    let types = |events: &Value| -> Vec<Value> {
        events.as_array().unwrap().iter().map(|event| event["type"].clone()).collect()
    };
    assert_eq!(types(&rust["events"]["events"]), types(&python["events"]["body"]["events"]));
    assert_eq!(rust["events"]["cursor"], python["events"]["body"]["cursor"]);
    let files = |snapshot: &Value| -> Vec<String> {
        snapshot["files"].as_object().unwrap().keys().cloned().collect()
    };
    assert_eq!(files(&rust["snapshot"]), files(&python["snapshot"]["body"]));
    test.close().await;
}

fn event(sequence: i32, event_type: &str, actor: &str, payload: Value) -> EventView {
    EventView {
        sequence,
        id: key(),
        event_type: event_type.into(),
        actor: actor.into(),
        artifact_id: None,
        payload,
        command_id: key(),
        created_at: "2026-01-01T00:00:00Z".parse::<Timestamp>().unwrap(),
    }
}

#[test]
fn internal_knowledge_commands_never_reach_the_public_boundary() {
    // The public boundary is a second line of defense for rows written by any adapter.
    let command = "limina _agent finding create --thread private-thread --title x";
    let leaked = public_event(&event(
        1,
        "runtime.claude-code",
        "limina:runtime",
        json!({
            "summary": format!("Recording with {command}"),
            "kind": "message",
            "text": format!("Recording the finding:\n\n```bash\n{command}\n```\nDone."),
            "input": command,
            "thread_id": "private-thread",
        }),
    ))
    .unwrap();
    let detail = serde_json::to_string(&leaked.detail).unwrap();
    assert!(!detail.contains("private-thread"));
    assert!(!detail.contains("limina _agent"));
    assert_eq!(leaked.detail["input"], Value::Null);
    let text = leaked.detail["text"].as_str().unwrap();
    assert!(text.contains("Recording the finding"));
    assert!(text.contains("Done."));
    assert_eq!(leaked.detail["summary"], "Recording with [internal Limina knowledge command]");
    assert_eq!(leaked.actor, "Limina");
    assert_eq!(leaked.created_at.to_rfc3339(), "2026-01-01T00:00:00+00:00");

    // A tool row's summary is replaced outright.
    let tool = public_event(&event(
        2,
        "runtime.codex",
        "limina:runtime",
        json!({"summary": command, "kind": "tool", "input": "ls"}),
    ))
    .unwrap();
    assert_eq!(tool.detail["summary"], "Updating durable project knowledge");
    assert_eq!(tool.detail["input"], "ls");
    // Other event types are not transcripts and are left alone.
    let other =
        public_event(&event(3, "runtime.turn_started", "limina:x", json!({"text": command})))
            .unwrap();
    assert_eq!(other.detail["text"], command);
}

#[test]
fn coordination_is_hidden_and_internal_fields_renamed() {
    for hidden in ["coordinator.claimed", "coordinator.released"] {
        assert!(public_event(&event(1, hidden, "limina:x", json!({}))).is_none());
    }
    let created = public_event(&event(
        1,
        "challenge.created",
        "Olivia Owner",
        json!({"slug": "p", "runtime_engine": "codex", "name": "P"}),
    ))
    .unwrap();
    assert_eq!(created.event_type, "project.created");
    assert_eq!(created.detail, detail(json!({"slug": "p", "name": "P", "runtime": "codex"})));
    let keys: Vec<&String> = created.detail.keys().collect();
    assert_eq!(keys, ["slug", "name", "runtime"]);

    let checkpoint = public_event(&event(
        2,
        "coordinator.checkpointed",
        "limina:1:abc",
        json!({
            "status": "RUNNING",
            "version": 3,
            "worker_id": "limina:1:abc",
            "continuation_id": "thread",
            "turn_id": "turn",
            "expires_at": "later",
            "thread_id": "thread",
        }),
    ))
    .unwrap();
    assert_eq!(checkpoint.event_type, "project.checkpoint");
    assert_eq!(checkpoint.actor, "Limina");
    assert_eq!(checkpoint.detail, detail(json!({"status": "RUNNING"})));

    let sent = public_event(&event(
        3,
        "inbox.message_sent",
        "Olivia Owner",
        json!({"message_id": "m-1", "kind": "STEER", "sequence": 1, "body": "Go."}),
    ))
    .unwrap();
    assert_eq!(sent.event_type, "guidance.received");
    let keys: Vec<&String> = sent.detail.keys().collect();
    assert_eq!(keys, ["kind", "sequence", "body", "guidance_id"]);
    assert_eq!(sent.detail["guidance_id"], "m-1");
    let acknowledged =
        public_event(&event(4, "inbox.message_acknowledged", "limina:x", json!({}))).unwrap();
    assert_eq!(acknowledged.event_type, "guidance.incorporated");
    assert_eq!(acknowledged.detail["guidance_id"], Value::Null);
}

#[test]
fn turn_prompt_preserves_context_and_adds_the_workspace_output_contract() {
    let expected: BTreeMap<String, String> =
        serde_json::from_str(include_str!("fixtures/app_prompt.json")).unwrap();
    let files = BTreeMap::from([
        ("mission/CHALLENGE.md".to_owned(), "# Mission\n\nImprove NDCG.\n".to_owned()),
        ("ACTIVE.md".to_owned(), "# Active\n\nNext.\n".to_owned()),
    ]);
    let resource = |name: &str, kind: &str, value: Option<&str>| ResourceView {
        id: key(),
        name: name.into(),
        resource_type: kind.into(),
        value: value.map(str::to_owned),
        configured: (kind == "SECRET").then_some(true),
        status: "ACTIVE".into(),
        created_by: "owner".into(),
        created_at: now(),
        updated_at: now(),
    };
    let resources = [
        resource(
            "SOURCE_URL",
            "VARIABLE",
            Some("https://example.invalid/a?b=\"c\"\\d\n\t\u{e9}\u{1}\u{7f}"),
        ),
        resource("SOURCE_TOKEN", "SECRET", None),
    ];
    let source = |kind: &str, name: &str, uri: &str, media_type: Option<&str>| Source {
        id: key(),
        name: name.into(),
        source_type: kind.into(),
        uri: uri.into(),
        media_type: media_type.map(str::to_owned),
        metadata: Map::new(),
        status: "ACTIVE".into(),
        created_at: now(),
        updated_at: now(),
    };
    let sources = [
        source("URL", "benchmark", "https://example.test/b", None),
        source("UPLOAD", "brief", "workspace://.limina/sources/x/brief.md", Some("text/markdown")),
        source("CONNECTOR", "empty", "github://repo", Some("")),
    ];
    let messages = [MessageView {
        id: key(),
        sequence: 3,
        kind: "STEER".into(),
        body: "Prioritize latency.\nThen recall.".into(),
        actor: "Olivia Owner".into(),
        status: "PENDING".into(),
        created_at: now(),
        acknowledged_at: None,
    }];

    for (prompt, expected) in [
        (turn_prompt("retrieval", &files, &resources, &sources, &messages), &expected["full"]),
        (turn_prompt("retrieval", &files, &[], &[], &[]), &expected["empty"]),
    ] {
        let start = prompt.find("## Completion and communication contract").unwrap();
        let end = prompt[start..].find("## Mission\n").unwrap() + start;
        let contract = &prompt[start..end];
        assert!(contract.contains("counts of notes or experiments are not progress"));
        assert!(contract.contains("existing project artifact IDs"));
        assert!(contract.contains("does not change KPI measurements"));
        let legacy = format!("{}{}", &prompt[..start], &prompt[end..]);
        assert_eq!(legacy, expected.as_str());
    }
}
